def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    component_sizes = []

    def dfs(node):
        count = 0
        stack = [node]
        while stack:
            curr = stack.pop()
            if not visited[curr]:
                visited[curr] = True
                count += 1
                for neighbor in adj[curr]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return count

    for i in range(1, n + 1):
        if not visited[i]:
            size = dfs(i)
            component_sizes.append(size)

    lucky_set = set()

    def is_lucky(num: int) -> bool:
        s = str(num)
        return all(c in '47' for c in s)

    for num in range(1, n + 1):
        if is_lucky(num):
            lucky_set.add(num)

    component_sizes.sort()

    if len(component_sizes) == 0:
        return "-1\n"

    min_roads = [float('inf')]

    for lucky_target in sorted(lucky_set):
