                visited_sum[size] = True
                queue.append((size, 1))

        if visited_sum[lucky_target]:
            min_roads[lucky_target] = 1
        else:
            idx = 0
            while idx < len(queue) and not visited_sum[lucky_target]:
                curr_sum, cnt = queue[idx]
                idx += 1

                for size in component_sizes:
                    if curr_sum + size <= lucky_target and not visited_sum[curr_sum + size]:
