    source = n
    sink = n + 1
    dinic = Dinic(n + 2)

    for i in range(n):
        dinic.add_edge(source, i, a[i])
        dinic.add_edge(i, sink, b[i])
        for j in range(n):
            if i == j or j in adj[i]:
                dinic.add_edge(i, j, float('inf') if i != j else 10000)

    total_a = sum(a)
    max_f = dinic.max_flow(source, sink)

    if max_f != total_a:
        return "NO\n"

    flow_matrix = [[0] * n for _ in range(n)]
    for u in range(n):
        for v, cap, _ in dinic.graph[u]:
            flow_matrix[u][v] = -cap if v < n else 0  # negative because we subtracted

    # Adjust flow by checking edges
    result = []
    for i in range(n):
