from collections import defaultdict, deque
import sys

def build_graph(edges):
    """Build adjacency list for undirected graph."""
    graph = defaultdict(list)
    for i, (u, v, w) in enumerate(edges):
        graph[u].append((v, i + 1, w))
        graph[v].append((u, i + 1, w))
    return graph

def bfs_edge_accessibility(graph, start, end):
    """Check if there's a path and return the path."""
    if start == end:
        return None
    dist = {start: 0}
    parent = {start: None}
    queue = deque([start])
    while queue:
        u = queue.popleft()
        if u == end:
            break
        for v, idx, w in graph[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                parent[v] = (u, idx, w)
                queue.append(v)
    if end not in dist:
        return None
    path = []
    v = end
    while v != start:
        p, idx, w = parent[v]
        path.append((p, v, idx, w))
        v = p
    return path[::-1]

def find_min_single_edge_cut(budget_edges, s, t):
    """Find minimum budget to disconnect s and t by removing 1 edge."""
    paths = []
    dist = {('bfs', s): 0}
    parent = {('bfs', s): None}
    queue = deque([('bfs', s)])

    while queue:
        (type_, u) = queue.popleft()
        if type_ == 'bfs' and u == t:
            break
        for v, idx, w in budget_edges[u]:
            if v not in dist:
                dist[(type_, v)] = dist[(type_, u)] + 1
                parent[(type_, v)] = (type_, u)
                queue.append((type_, v))

    if t not in dist:
        return None, 0, []

    path = []
    v = t
    while v != s:
        p = parent[('bfs', v)]
        idx, w = next(edge for edge in budget_edges[p] if edge[0][0] == v)
        path.append(idx)
        v = p

