            T = (W * MOD * inv[2 * MOD - (2 * i + n) % MOD] % MOD * MOD) % MOD
            E = (v[n] * comb) % MOD
            term = (term * (E - T)) % MOD
        else:
            term = (term * v[n]) % MOD

        ans = (ans + term) % MOD

    return str(ans)
