        for pos1, t1, pos2, t2 in rules:
            if char_type(word[pos1-1]) == t1 and char_type(word[pos2-1]) != t2:
                return False
        return True

    def propagate(assignments):
        changed = True
        while changed:
            changed = False
            temp_assign = assignments.copy()
            impossible = False

            for pos1, t1, pos2, t2 in rules:
                if pos1 - 1 in temp_assign and temp_assign[pos1-1] == t1:
                    if pos2 - 1 not in temp_assign:
                        temp_assign[pos2-1] = t2
                        changed = True
                    elif temp_assign[pos2-1] != t2:
                        impossible = True
                        break

            if impossible:
                return None
            assignments = temp_assign if changed else assignments

        for pos in assignments:
            if assignments[pos] in ('V', 'C'):
                continue
            return None

        return assignments

    def solve(idx, current_word, assignments):
        if idx == n:
            return current_word[:] if check_valid(current_word) else None

        start_char = ord(target[idx]) - ord('a') if idx < len(target) else 0

        for i in range(start_char, l):
            c = alphabet[i]
            current_word.append(c)

            # Build new assignments
            new_assign = assignments.copy() if assignments else {}
            new_assign[idx] = char_type(c)

            result = propagate(new_assign)
            if result is not None:
                found = solve(idx + 1, current_word, new_assign)
                if found:
                    return found

            current_word.pop()

        return None

    result = solve(0, [], None)
    return ''.join(result) if result else "-1"
