                    for direction in dir_names:
                        dr, dc = directions[direction]
                        nr, nc = curr_x + dr, curr_y + dc
                        if 0 <= nr < n and 0 <= nc < n:
                            if can_see_light_in_direction(curr_x, curr_y, dr, dc):
                                result.append(direction)
