                    if md:
                        result.append(md)
                        curr_x, curr_y = prev_r, prev_c

    # If we can't visit all lights, try a different order with priority on reaching lights
    # But first, check if we can finish
    all_off = True
    for lr, lc in lights_on:
        if grid[lr][lc] == 1:
            all_off = False
            break

    if all_off:
        # Return to start
        while (curr_x, curr_y) != (start_x, start_y):
            for direction in dir_names:
                dr, dc = directions[direction]
