    maxy = int(parts[1])
    w = int(parts[2])

    # Precompute rev and calculate for each pair
    def rev(n):
        return int(str(n)[::-1])

    # Precompute lucky status for pairs up to max(maxx, maxy)
    limit = max(maxx, maxy)
    is_lucky = [[False] * (limit + 1) for _ in range(limit + 1)]

    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            if a * b == rev(a) * rev(b):
                is_lucky[a][b] = True
            else:
                is_lucky[a][b] = False

    # Since maxy is up to 10^5 and maxx up to 10^5, we can't compute full table
    # Instead, we'll check strategically
    def count_lucky(x, y):
        count = 0
        for a in range(1, x + 1):
            for b in range(1, y + 1):
                if a * b == rev(a) * rev(b):
                    count += 1
        return count

    # We need to find minimum x*y such that count_lucky(x,y) >= w
    # Search strategy: check various combinations
    best_x, best_y = -1, -1
    best_product = float('inf')

    # Try prioritizing small x and y first (brute force for small values)
    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            prod = x * y
            if prod >= best_product:
                continue
            cnt = count_lucky(x, y)
            if cnt >= w:
                best_x, best_y = x, y
                best_product = prod
                break
        if best_x != -1:
            break

    if best_x == -1:
        return '-1'

    return f"{best_x} {best_y}"
