            return True

        # Check if all elements are zero
        if all(x == 0 for x in seq):
            return True

        # If first element is zero, all must be zero for it to be a GP
        if seq[0] == 0:
            return all(x == 0 for x in seq)

        # Calculate the ratio from first two elements
        r = seq[1] / seq[0]

        # Check that all subsequent elements follow the ratio
        for i in range(2, m):
            # Use a small epsilon for floating point comparison
            if abs(seq[i] - seq[i-1] * r) > 1e-9:
                return False

        return True

    # Check if the original array is a geometric progression
    if is_gp(arr):
        return '0\n'

    # Try removing one element at a time and check if the result is a GP
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return '1\n'

    # If not possible
    return '2\n'
