def solution(input_str):
    n, r = map(int, input_str.split())

    # Generate all valid integer points within distance r from origin
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                points.append((x, y))

    # Sort points by their distance from origin (descending)
    points_sorted = sorted(points, key=lambda p: p[0]**2 + p[1]**2, reverse=True)
    point_index = {p: i for i, p in enumerate(points_sorted)}

    best_score = -1
    best_arrangement = []

    def calculate_score(arrangement):
        """Calculate sum of squared distances between all pairs of points"""
        score = 0
        for i in range(len(arrangement)):
            for j in range(i + 1, len(arrangement)):
                dx = arrangement[i][0] - arrangement[j][0]
                dy = arrangement[i][1] - arrangement[j][1]
                score += dx*dx + dy*dy
        return score

    # Try different greedy approaches with different starting points
    for start_idx in range(min(n, len(points_sorted))):
        used_points = []
        for seed in range(5):  # Try 5 different seeds
            current = []
            excluded = set()  # Points already in current arrangement

            # Shuffle indices for randomness
            indices = list(range(len(points_sorted)))

            def greedy_build(pos):
                if pos == n:
                    if len(current) < n:
                        return  # Need exactly n points
                    score = calculate_score(current)
                    nonlocal best_score, best_arrangement
                    if score > best_score:
                        # Apply variations to potentially escape suboptimal
                        best_score = score
                        best_arrangement = current[:]
                    return 0

                best_choice = -1
                best_val = float('-inf')

                full_eval = True
                for idx in indices:
                    if idx in excluded:
                        continue
                    cand = points_sorted[idx]
                    val = calculate_score(current)
                    # Add the contribution from this new point
                    for p in current:
                        dx = cand[0] - p[0]
                        dy = cand[1] - p[1]
                        val += dx*dx + dy*dy
                    if val > best_val or best_choice == -1:
                        best_val = val
                        best_choice = idx

            greedy_build(0)

            if len(current) < n:
                # Use all remaining points to reach n
                while len(current) < n:
                    try:
                        idx = indices[len(current)]
                        if idx not in excluded:
                            excluded.add(idx)
                            current.append(points_sorted[idx])
                            indices.remove(idx)
                    except:
                        break

        # Ensure we have exactly n points
        while len(best_arrangement) < n:
            if len(points_sorted) > 0:
                p = points_sorted[0]
                if n > 1:
                    best_arrangement.append(p)

    # Final brute force for small n
    if n <= 4:
        from itertools import combinations_with_replacement

        for combo in combinations_with_replacement(range(len(points)), n):
            arrangement = [points[i] for i in combo]
            score = calculate_score(arrangement)
            if score > best_score:
                best_score = score
                best_arrangement = arrangement[:]

    # Format output
    lines = [str(best_score)]
    for p in best_arrangement:
        lines.append(f"{p[0]} {p[1]}")
    return "\n".join(lines)

