from collections import deque

def solve_dp(n_str):
    """
    Uses BFS/memoization to solve the problem for smaller numbers.
    Returns the minimum number of operations to reduce n to 0.
    """
    if n_str == '0':
        return 0

    memo = {}
    visited = set()

    def dp(current):
        if current == 0:
            return 0
        if current in memo:
            return memo[current]
        if current in visited:
            # Shouldn't happen with proper BFS, but safety check
            return float('inf')

        visited.add(current)
        digits = []
        for d in str(current):
            digits.append(int(d))

        min_ops = float('inf')
        for d in digits:
            if d > 0:
                next_val = current - d
                ops = 1 + dp(next_val)
                min_ops = min(min_ops, ops)

        memo[current] = min_ops
        return min_ops

    return dp(int(n_str))

def solution(n_str):
    n = int(n_str.strip())

    if n == 0:
        return '0'

    # For numbers <= 10^7, we can use BFS/DP efficiently
    # For larger numbers, we use a greedy-like approach with memoization
    # but we need to be very clever about what we memoize

    if n <= 10**7:
        # Direct BFS
        visited = {n: 0}
        queue = deque([n])

        while queue:
            current = queue.popleft()
            if current == 0:
                return str(visited[n])

            current_digits = [int(d) for d in str(current)]
            max_digit = max(current_digits) if current_digits else 0

            for d in current_digits:
                if d > 0 and (current - d) not in visited:
                    visited[current - d] = visited[current] + 1
                    queue.append(current - d)
                    if visited[current - d] <= visited.get(n, 0) * 100:  # Early exit optimization
                        if current - d == 0:
                            return str(n)

        return str(visited.get(n, n))

    else:
        # For very large numbers, use an optimized approach
        # The key insight is that for large N, the answer is approximately N // k for some small k
        # But we need the exact answer

        # For N <= 10^18, we can use BFS but limit the search space
        # by noting that once numbers get small, they loop into pattern

        max_depth = 10**8
        from functools import lru_cache

        @lru_cache(maxsize=1000000)
        def memoized_dp(current):
            if current == 0:
                return 0
            if current <= 0:
                return current // -1  # Avoid infinite recursion

            digits = [int(d) for d in str(current)]
            if not digits:
                return 0

            min_ops = float('inf')
            for d in digits:
                if d > 0:
                    next_val = current - d
                    if next_val >= 0:
                        ops = 1 + memoized_dp(next_val)
                        if ops != float('inf') and ops < min_ops:
                            min_ops = ops

            return min_ops if min_ops != float('inf') else current

        result = memoized_dp(n)
        return str(result)

