import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, w, v, u = map(int, lines[0].split())

    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    # Find for each y in [0, w], the x-range of intersection with the polygon
    # Since the polygon is convex and we need to find if it covers x=0 at various times

    # First, check if the polygon crosses the line x=0
    # Compute the x-interval [L(y), R(y)] for each y

    # For a vertex-based convex polygon, edges go between consecutive vertices
    # For each edge, compute the y-range and x at a given y

    def get_intersection_x(edge_start, edge_end, y):
        """Get the x-coordinate on the edge at height y, or None if edge doesn't span y"""
        x1, y1 = edge_start
        x2, y2 = edge_end

        if math.isclose(y1, y2):
            return None if y != y1 else x1

        t = (y - y1) / (y2 - y1)
        return x1 + t * (x2 - x1)

    def edge_is_below(edge_start, edge_end, y):
        """Check if the edge is below height y (all Y coordinates < y)"""
        return max(edge_start[1], edge_end[1]) < y - 1e-9

    def edge_is_above(edge_start, edge_end, y):
        """Check if the edge is above height y (all Y coordinates > y)"""
        return min(edge_start[1], edge_end[1]) > y + 1e-9

    # Find minimum and maximum x for each y level by computing intersections with edges
    min_x_by_y = {}
    max_x_by_y = {}

    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i + 1) % n]

        min_y = min(y1, y2)
        max_y = max(y1, y2)

        for yi in range(min_y, max_y + 1):
            x_at = get_intersection_x((x1, y1), (x2, y2), yi)
            if x_at is not None:
                if yi not in min_x_by_y:
                    min_x_by_y[yi] = x_at
                    max_x_by_y[yi] = x_at
                else:
                    min_x_by_y[yi] = min(min_x_by_y[yi], x_at)
                    max_x_by_y[yi] = max(max_x_by_y[yi], x_at)

    # Get continuous function approximation: for any y, find [L(y), R(y)]
    # For this, linearly interpolate between computed points (since polygon is convex)

    def get_yyer(device):
        if device == 'v':
            values = list(min_x_by_y.items())
        else:
            values = list(max_x_by_y.items())
        if not values:
            return 10**10 if device == 'v' else -10**10
        return list(zip(*sorted(values)))

    sorted_y_min = sorted(min_x_by_y.keys())
    sorted_y_max = sorted(max_x_by_y.keys())

    def get_L(y):
        """Minimum x at height y"""
        if not sorted_y_min:
            return 10**10
        idx = 0
        if y <= sorted_y_min[0]:
            return min_x_by_y[sorted_y_min[0]] if y < sorted_y_min[0] - 1e-9 else 10**10 + (sorted_y_min[0] - y) * 10**18
        if y >= sorted_y_min[-1]:
            return sorted_y_min[-1] * 10**10
        for i in range(len(sorted_y_min) - 1):
            y1, y2 = sorted_y_min[i], sorted_y_min[i+1]
            if y1 <= y <= y2:
                x1, x2 = min_x_by_y[y1], min_x_by_y[y2]
                if math.isclose(y1, y2):
                    return x1
                t = (y - y1) / (y2 - y1)
                return x1 + t * (x2 - x1)
        return min_x_by_y[sorted_y_min[-1]]

