        """Check if placing new_color at (r,c) violates K4 in 2x2 starting at (r,c)"""
        if r < 0 or c < 0 or r + 1 >= n or c + 1 >= m:
            return True
        colors = []
        for dr, dc in [(0, 0), (0, 1), (1, 0), (1, 1)]:
            colors.append(grid[r + dr][c + dc])
        colors[0] = new_color  # Replace (r,c) with new_color
        non_zero = [c for c in colors if c != '0']
        if len(set(non_zero)) > 4:  # Should be at most 4
            return False
        # Also check: if we have more than 3 distinct non-zero colors including the new one
        if len(non_zero) >= 4:
            return True  # All 4 must be unique, so if we already have 3+ existing, new one might still work
        return True

    def check_2x2_constraint(r, c, new_color):
        """Check if placing new_color at (r,c) violates K4 constraints"""
        # (r,c) belongs to up to 4 different 2x2 grids
        # Check each 2x2 grid position

        # Top-left of 2x2 that contains (r,c)
        for start_r in [r - 1, r]:
            for start_c in [c - 1, c]:
                if 0 <= start_r and 0 <= start_r + 1 < n and 0 <= start_c and 0 <= start_c + 1 < m:
                    colors = []
                    for dr, dc in [(0, 0), (0, 1), (1, 0), (1, 1)]:
                        nc = grid[start_r + dr][start_c + dc]
                        colors.append(nc)
                    # Replace the one at (r,c) with new_color
                    if start_r == r - 1 and start_c == c - 1:
                        colors[0] = new_color
                    elif start_r == r - 1 and start_c == c:
                        colors[1] = new_color
                    elif start_r == r and start_c == c - 1:
                        colors[2] = new_color
                    else:  # start_r == r and start_c == c
