    def get_displacement(move_char):
        """What position change does a button press normally cause?"""
        if move_char == 'U':
            return (-1, 0)
        elif move_char == 'D':
            return (1, 0)
        elif move_char == 'L':
            return (0, -1)
        elif move_char == 'R':
            return (0, 1)
        return (0, 0)

    def move_based_on_displacement(r_change, c_change, swapLR, swapUD):
        """Given a displacement we want to achieve, which button produces it?"""
        if swapLR and swapUD:
            # Both swapped
            if r_change == -1:  # going up, but U produces down
                return 'U'  # U becomes U (down direction)
            elif r_change == 1:  # going down
                return 'U'  # D becomes U (but we need D for down... wait)
            # Need fresh logic
        if r_change and c_change == 0:
            # Vertical movement
            if swapUD:
                if r_change == -1:
                    return 'U'  # U is now down direction
                elif r_change == 1:
                    return 'U'  # need down, so press U (which becomes D)
            else:
                if r_change == -1:
                    return 'U'
                elif r_change == 1:
                    return 'D'
        elif c_change and r_change == 0:
            # Horizontal movement
            if swapLR:
                if c_change == -1:
                    return 'L'  # L becomes right
                elif c_change == 1:
                    return 'R'  # R becomes left
            else:
                if c_change == -1:
                    return 'L'
                elif c_change == 1:
                    return 'R'
        return 'L'

    def get_actual_move_from_direction(direction):
        """Given which direction we want to go, what button do we press?"""
        r_change, c_change = -1 if direction == 'U' else (1 if direction == 'D' else (0 if c_change > 0 else -1))
        if r_change == -1:
            return 'U'
        elif r_change == 1:
            return 'D'
        elif c_change == -1 and not swapLR:
            return 'L'
        elif c_change == 1 and not swapLR:
            return 'R'
        return 'D'

    def next_position_from_move(r, c, button, swapLR, swapUD):
        """Where does pressing button take us?"""
        dr, dc = 0, 0
        if swapUD:
            if button == 'U':
                dr = 1
            elif button == 'D':
                dr = -1
        else:
            if button == 'U':
                dr = -1
            elif button == 'D':
                dr = 1

        if swapLR:
            if button == 'L':
                dc = 1
            elif button == 'R':
                dc = -1
        else:
            if button == 'L':
                dc = -1
            elif button == 'R':
                dc = 1

        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < m and board[nr][nc] != '*':
            return (nr, nc)
        return (-1, -1)

    def target_direction_to_pos(curr, target):
        """What direction (U/D/L/R) goes from curr to target in normal world?"""
        curr_r, curr_c = curr
        target_r, target_c = target
        dr = target_r - curr_r
        dc = target_c - curr_c

        if dr == -1 and dc == 0:
            return 'U'
        elif dr == 1 and dc == 0:
            return 'D'
        elif dr == 0 and dc == -1:
            return 'L'
        elif dr == 0 and dc == 1:
            return 'R'
        return None

    # BFS to find shortest path
    queue = deque([(start_pos[0], start_pos[1], "")])
    visited = set([start_pos])
    found = False
    best_path = ""

    while queue:
        r, c, path = queue.popleft()

        if (r, c) == finish_pos:
            best_path = path
            found = True
            break

        if len(path) * 2 > n * m * 2:
            continue

        # Try all buttons
        for btn in ['U', 'D', 'L', 'R']:
            nr, nc = next_position_from_move(r, c, btn, swapLR, swapUD)
            if nr == -1:
                continue

            new_pos = (nr, nc)
            if new_pos not in visited:
                visited.add(new_pos)
                queue.append((nr, nc, path + btn))

    if found and best_path:
        return best_path + '\n'
    return ""
